10	func TestMiddlewareChaining(t *testing.T) {
11		var order []string
12	
13		mw1 := func(next JobHandler) JobHandler {
14			return func(ctx context.Context) error {
15				order = append(order, "before-1")
16				err := next(ctx)
17				order = append(order, "after-1")
18				return err
19			}
20		}
21	
22		mw2 := func(next JobHandler) JobHandler {
23			return func(ctx context.Context) error {
24				order = append(order, "before-2")
25				err := next(ctx)
26				order = append(order, "after-2")
27				return err
28			}
29		}
30	
31		handler := func(_ context.Context) error {
32			order = append(order, "handler")
33			return nil
34		}
35	
36		chain := Chain(mw1, mw2)
37		wrapped := chain(handler)
38	
39		if err := wrapped(context.Background()); err != nil {
40			t.Fatalf("wrapped handler failed: %v", err)
41		}
42	
43		expected := []string{"before-1", "before-2", "handler", "after-2", "after-1"}
44		if len(order) != len(expected) {
45			t.Fatalf("expected %d calls, got %d", len(expected), len(order))
46		}
47	
48		for i, want := range expected {
49			if order[i] != want {
50				t.Errorf("order[%d] = %q, want %q", i, order[i], want)
51			}
52		}
53	}
