55	func TestRecoveryMiddleware(t *testing.T) {
56		var panicRecovered atomic.Bool
57	
58		onPanic := func(_ string, _ interface{}) {
59			panicRecovered.Store(true)
60		}
61	
62		handler := func(_ context.Context) error {
63			panic("simulated panic")
64		}
65	
66		recovery := Recovery(onPanic)
67		wrapped := recovery(handler)
68	
69		// Should not panic, error should be returned
70		err := wrapped(withJobName(context.Background(), "test-job"))
71		if err == nil {
72			t.Error("expected error from recovered panic")
73		}
74	
75		if !panicRecovered.Load() {
76			t.Error("panic handler was not called")
77		}
78	}
