80	func TestLoggingMiddleware(t *testing.T) {
81		var loggedStart, loggedEnd atomic.Bool
82		var loggedError atomic.Bool
83	
84		logger := &testLogger{
85			onInfo: func(msg string, _ ...interface{}) {
86				if msg == "Job started" {
87					loggedStart.Store(true)
88				} else if msg == "Job completed" {
89					loggedEnd.Store(true)
90				}
91			},
92			onError: func(msg string, _ ...interface{}) {
93				if msg == "Job failed" {
94					loggedError.Store(true)
95				}
96			},
97		}
98	
99		// Test successful execution
100		handler := func(_ context.Context) error {
101			return nil
102		}
103	
104		logging := Logging(logger)
105		wrapped := logging(handler)
106	
107		if err := wrapped(withJobName(context.Background(), "test-job")); err != nil {
108			t.Fatalf("handler failed: %v", err)
109		}
110	
111		if !loggedStart.Load() {
112			t.Error("start was not logged")
113		}
114		if !loggedEnd.Load() {
115			t.Error("end was not logged")
116		}
117	
118		// Test error handling
119		handlerErr := func(_ context.Context) error {
120			return errors.New("job error")
121		}
122	
123		wrappedErr := logging(handlerErr)
124		_ = wrappedErr(withJobName(context.Background(), "test-job-error"))
125	
126		if !loggedError.Load() {
127			t.Error("error was not logged")
128		}
129	}
130	
131	type testLogger struct {
132		onInfo  func(msg string, args ...interface{})
133		onError func(msg string, args ...interface{})
134	}
135	
136	func (l *testLogger) Info(msg string, args ...interface{}) {
137		if l.onInfo != nil {
138			l.onInfo(msg, args...)
139		}
140	}
141	
142	func (l *testLogger) Error(msg string, args ...interface{}) {
143		if l.onError != nil {
144			l.onError(msg, args...)
145		}
146	}
