205	// AuthInterceptor enforces authentication and anonymous-access policy for Connect
206	// handlers by delegating to the shared Authorizer. Role-based authorization
207	// (admin checks) remains in the service layer.
208	type AuthInterceptor struct {
209		authorizer *Authorizer
210	}
211	
212	// NewAuthInterceptor creates a new auth interceptor backed by the shared Authorizer.
213	func NewAuthInterceptor(authorizer *Authorizer) *AuthInterceptor {
214		return &AuthInterceptor{authorizer: authorizer}
215	}
216	
217	func (in *AuthInterceptor) WrapUnary(next connect.UnaryFunc) connect.UnaryFunc {
218		return func(ctx context.Context, req connect.AnyRequest) (connect.AnyResponse, error) {
219			header := req.Header()
220			authHeader := header.Get("Authorization")
221	
222			result := in.authorizer.Authenticate(ctx, authHeader)
223			if err := in.authorizer.CheckAccess(ctx, req.Spec().Procedure, result); err != nil {
224				return nil, connect.NewError(connect.CodeUnauthenticated, err)
225			}
226	
227			ctx = auth.ApplyToContext(ctx, result)
228	
229			return next(ctx, req)
230		}
231	}
232	
233	func (*AuthInterceptor) WrapStreamingClient(next connect.StreamingClientFunc) connect.StreamingClientFunc {
234		return next
235	}
236	
237	func (*AuthInterceptor) WrapStreamingHandler(next connect.StreamingHandlerFunc) connect.StreamingHandlerFunc {
238		return next
239	}
